<!-- This file is generated by AI. -->

<!--
  场景文件被外部修改时的裁决对话框 (四个分支的实现见下方各函数)。

  **「保留编辑器内容」必须写盘**: 只"保留"而不写盘, 磁盘上仍是被外部改过的那一份, 下一次
  变更检测会再次弹窗, 用户会陷入"每次都选保留、每次都再问一遍"的死循环。

  **裁决必须发生在历史重新对齐之前**: 用户在 git 合并页里改完内容会再次改变行号, 先对齐的话
  对齐结果立刻失效。

  按 Esc / 点背景 = 暂不决定, 这时**要把它记下来** (变更检测每隔几秒跑一次, 不记等于没按);
  记录以磁盘内容哈希为键, 因此磁盘**再次**变化时会重新询问。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { fs } from '../lib/fs';
  import { useAppStore } from '../state/store.svelte';
  import { makeDiffTab } from '../tabs/model';
  import { voiceController } from '../voice/controller';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';

  let {
    scenePath,
    /** 磁盘内容预览, null 表示还没读到 (读到之前不给「加载磁盘内容」点) */
    diskPreview,
    inRepository,
    /** 用户做出了裁决 (无论选了哪一项) */
    onResolved,
    /** 用户按 Esc / 点背景: 暂不决定, 且不要为同一个磁盘状态再问一遍 */
    onDismiss,
  }: {
    scenePath: string;
    diskPreview: string | null;
    inRepository: boolean;
    onResolved: () => void;
    onDismiss: () => void;
  } = $props();

  let busy = $state(false);
  let error = $state<string | null>(null);

  const store = useAppStore.getState();

  function baseNameOf(path: string): string {
    return path.split(/[\\/]/).pop() ?? path;
  }

  /** 编辑器里这一份的当前内容 (没有打开的文档时按空处理)。 */
  function editorContent(): string {
    return store.documents.find((item) => item.path === scenePath)?.content ?? '';
  }

  async function run(action: () => Promise<unknown>): Promise<void> {
    busy = true;
    error = null;
    try {
      await action();
      onResolved();
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }

  /**
   * 备份文件路径: **同目录**下加一个带时间戳的后缀, 而不是放临时目录 —— 用户回头要找它,
   * 放在项目里才找得到。后缀不是 `.txt` 结尾, 因此不会被当成场景文件。
   */
  function backupTarget(): string {
    const separator = scenePath.includes('\\') ? '\\' : '/';
    const directory = scenePath.slice(0, scenePath.lastIndexOf(separator));
    const stamp = new Date().toISOString().replace(/[:.]/g, '-');
    return `${directory}${separator}${baseNameOf(scenePath)}.ink-backup-${stamp}`;
  }

  /** 项目内相对路径 (差异页要的是这个, 不是绝对路径)。 */
  function relativeToProject(): string {
    const projectPath = store.projectPath;
    if (!projectPath) return scenePath;
    const base = projectPath.replace(/\\/g, '/').replace(/\/+$/, '');
    const full = scenePath.replace(/\\/g, '/');
    return full.toLowerCase().startsWith(`${base.toLowerCase()}/`) ? full.slice(base.length + 1) : full;
  }

  /** 分支 1: 先把手上的内容另存一份, 再加载磁盘。 */
  function backupAndTakeDisk(): void {
    void run(async () => {
      await fs.writeText(backupTarget(), editorContent());
      const disk = await fs.readTextLossy(scenePath);
      store.updateDocument(scenePath, { content: disk, dirty: false });
      voiceController.setDiskHash(scenePath, '');
      await voiceController.refreshCard(scenePath, disk);
      await voiceController.realignCard(scenePath);
    });
  }

  /** 分支 2: 把编辑器里这一份写回磁盘, 此后以它为准。 */
  function keepEditor(): void {
    void run(async () => {
      await fs.writeText(scenePath, editorContent());
      store.updateDocument(scenePath, { dirty: false });
      await voiceController.realignCard(scenePath);
    });
  }

  /** 分支 4: 放弃编辑器这一份, 改用磁盘的。 */
  function takeDisk(): void {
    void run(async () => {
      const disk = await fs.readTextLossy(scenePath);
      store.updateDocument(scenePath, { content: disk, dirty: false });
      voiceController.setDiskHash(scenePath, '');
      await voiceController.refreshCard(scenePath, disk);
      await voiceController.realignCard(scenePath);
    });
  }

  /** 分支 3: 打开差异页逐块取舍。 */
  function openGitMerge(): void {
    if (!inRepository) return;
    store.openTab(
      makeDiffTab({
        file: relativeToProject(),
        title: '合并场景改动',
        diffKind: 'unstaged',
      })
    );
    onResolved();
  }
</script>

<AppDialog title="场景文件已被外部修改" description={scenePath} size="medium" closeOnBackdrop onClose={onDismiss}>
  <p class="voice-dialog-hint">
    {inRepository
      ? '这份文件在磁盘上被改过（例如切换分支、外部编辑器或另一个窗口），编辑器里这一份与它不同。'
      : '这份文件在磁盘上被改过（例如外部编辑器或另一个窗口），编辑器里这一份与它不同。'}
    「保留编辑器内容」会把编辑器里的这一份**写回磁盘**（此后以它为准, 不会再反复询问）, 「加载磁盘内容」改用磁盘上的那一份,
    「用 git 合并」打开差异页逐块取舍。 无论选哪一项, Ink 之后都会把配音历史重新对齐到最终的对话列表; 按 Esc 表示暂不决定。
  </p>

  {#if error}
    <p class="voice-error">{error}</p>
  {/if}

  {#snippet footerLeading()}
    <Button disabled={busy} title="先把编辑器里的内容另存一份再加载磁盘" onclick={backupAndTakeDisk}>
      备份后加载磁盘
    </Button>
  {/snippet}

  {#snippet footer()}
    <Button disabled={busy} title="用编辑器里的内容覆盖磁盘文件（此后以这一份为准）" onclick={keepEditor}>
      保留编辑器内容（覆盖磁盘）
    </Button>
    <Button
      disabled={busy || !inRepository}
      title={inRepository ? '打开独立的 git 合并页面' : '当前项目不在 git 仓库中'}
      onclick={openGitMerge}
    >
      用 git 合并
    </Button>
    <Button appearance="primary" disabled={busy || diskPreview === null} onclick={takeDisk}>加载磁盘内容</Button>
  {/snippet}
</AppDialog>
